import { StudioCtxContext } from "@/wab/client/contexts/StudioContexts";
import {
  DefaultActionChipProps,
  PlasmicActionChip,
} from "@/wab/client/plasmic/plasmic_kit_state_management/PlasmicActionChip";
import type { ModelRef } from "@/wab/client/studio-ctx/model-snapshots";
import { ensure } from "@/wab/shared/common";
import {
  EventHandler,
  Interaction,
} from "@/wab/shared/model/classes";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import * as React from "react";
import { useStore } from "zustand";
import { createStore } from "zustand/vanilla";

export interface ActionChipProps extends DefaultActionChipProps {
  eventHandler: EventHandler | undefined | null;
  onClick: () => void;
  "data-plasmic-prop"?: string;
}

/** Stable fallback stores keep the hook path identical for absent models. */
const emptyInteractionsStore = createStore<readonly ModelRef<Interaction>[]>(
  () => Object.freeze([]),
);
const emptyInteractionNameStore = createStore<string>(() => "");

function ActionChip_(props: ActionChipProps, ref: HTMLElementRefOf<"div">) {
  const {
    eventHandler,
    onClick,
    "data-plasmic-prop": dataPlasmicProp,
    ...rest
  } = props;
  const studioCtx = React.useContext(StudioCtxContext);
  const modelSnapshots = eventHandler
    ? ensure(
        studioCtx,
        "ActionChip requires StudioCtx for a bound event handler",
      ).modelSnapshots
    : undefined;
  const interactions = useStore(
    eventHandler && modelSnapshots
      ? modelSnapshots.field(eventHandler, "interactions")
      : emptyInteractionsStore,
  );
  const interaction = interactions.length === 1 ? interactions[0] : undefined;
  const interactionName = useStore(
    interaction && modelSnapshots
      ? modelSnapshots.field(
          modelSnapshots.resolve(interaction),
          "interactionName",
        )
      : emptyInteractionNameStore,
  );
  const actionName =
    interactions.length === 1
      ? interactionName
      : `${interactions.length} actions`;

  return (
    <PlasmicActionChip
      root={{
        ref,
        "data-plasmic-prop": dataPlasmicProp,
      }}
      {...rest}
      actionName={actionName}
      onClick={onClick}
    />
  );
}

const ActionChip = React.forwardRef(ActionChip_);
export default ActionChip;
